export function selectPikachuSpecialPhaseHurtboxes(sheet: string, localFrame: number) {
  if (!Number.isFinite(localFrame) || localFrame < 0) return null;
  return PIKACHU_SPECIAL_PHASE_AUTHORED_HURTBOX_POSES.find(row => row.sheet === sheet
    && localFrame >= row.startElapsed && (row.endElapsed === null || localFrame < row.endElapsed))?.hurtboxes ?? null;
}
